{"content": "document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('search-input');
    const searchButton = document.getElementById('search-button');
    const resultsList = document.getElementById('results-list');
    const favoritesList = document.getElementById('favorites-list');

    let favorites = JSON.parse(localStorage.getItem('favorites')) || [];

    // --- Favorites Management ---
    function renderFavorites() {
        favoritesList.innerHTML = '';
        if (favorites.length === 0) {
            favoritesList.innerHTML = '<li>No favorites yet.</li>';
            return;
        }
        favorites.forEach(restaurant => {
            const li = document.createElement('li');
            li.textContent = restaurant.name;

            const removeBtn = document.createElement('button');
            removeBtn.textContent = 'Remove';
            removeBtn.className = 'favorite-btn remove-btn';
            removeBtn.onclick = () => removeFromFavorites(restaurant.id);

            li.appendChild(removeBtn);
            favoritesList.appendChild(li);
        });
    }

    function addToFavorites(restaurant) {
        if (!favorites.some(fav => fav.id === restaurant.id)) {
            favorites.push(restaurant);
            localStorage.setItem('favorites', JSON.stringify(favorites));
            renderFavorites();
        }
    }

    function removeFromFavorites(id) {
        favorites = favorites.filter(fav => fav.id !== id);
        localStorage.setItem('favorites', JSON.stringify(favorites));
        renderFavorites();
    }

    // --- Search Logic (Placeholder) ---
    searchButton.addEventListener('click', performSearch);
    searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            performSearch();
        }
    });

    function performSearch() {
        const query = searchInput.value.trim();
        resultsList.innerHTML = '<li>Searching...</li>';

        // In a real app, this would be an API call (e.g., fetch('/api/search?q=' + query))
        // For MVP, we use mock data based on the query.
        setTimeout(() => {
            resultsList.innerHTML = '';
            if (!query) {
                resultsList.innerHTML = '<li>Please enter a search term.</li>';
                return;
            }

            const mockResults = [
                { id: 1, name: `The Best Pizza Place (${query})`, cuisine: 'Italian' },
                { id: 2, name: `Burger Joint near ${query}`, cuisine: 'American' },
                { id: 3, name: `Sushi Express`, cuisine: 'Japanese' }
            ].filter(r => r.name.toLowerCase().includes(query.toLowerCase()) || r.cuisine.toLowerCase().includes(query.toLowerCase()));

            if (mockResults.length === 0) {
                resultsList.innerHTML = '<li>No restaurants found matching your search.</li>';
                return;
            }

            mockResults.forEach(restaurant => {
                const li = document.createElement('li');
                li.innerHTML = `
                    <span>${restaurant.name} (${restaurant.cuisine})</span>
                    <button class="favorite-btn add-btn" data-id="${restaurant.id}" data-name="${restaurant.name}">Favorite</button>
                `;
                resultsList.appendChild(li);
            });

            // Attach event listeners to new favorite buttons
            document.querySelectorAll('.add-btn').forEach(button => {
                button.addEventListener('click', (e) => {
                    const id = parseInt(e.target.dataset.id);
                    const name = e.target.dataset.name;
                    addToFavorites({ id, name });
                });
            });

        }, 500); // Simulate network delay
    }

    // Initial render
    renderFavorites();
});", "path": "FoodSearchMVP_Web_Simple/app.js"}

