import os

app = Flask(__name__)

# --- Configuration ---
# Set the directory where static files (index.html, app.js, style.css) are located
STATIC_DIR = 'FoodSearchMVP_Web_Simple'

# --- Mock Data (for future backend integration) ---
MOCK_RESTAURANTS = [
    {"id": 101, "name": "The Italian Place", "cuisine": "Italian", "rating": 4.5},
    {"id": 102, "name": "Burger Heaven", "cuisine": "American", "rating": 4.2},
    {"id": 103, "name": "Sushi Spot", "cuisine": "Japanese", "rating": 4.8},
    {"id": 104, "name": "Taco Town", "cuisine": "Mexican", "rating": 4.0},
]

# --- Routes ---

@app.route('/')
def index():
    """Serves the main HTML file."""
    return send_from_directory(STATIC_DIR, 'index.html')

@app.route('/<path:path>')
def serve_static(path):
    """Serves CSS, JS, and other static assets."""
    return send_from_directory(STATIC_DIR, path)

@app.route('/api/search', methods=['GET'])
def search_restaurants():
    """API endpoint for searching restaurants (currently mocks the frontend logic)."""
    query = request.args.get('q', '').lower()

    if not query:
        return jsonify({"results": []})

    results = [
        r for r in MOCK_RESTAURANTS 
        if query in r['name'].lower() or query in r['cuisine'].lower()
    ]

    return jsonify({"results": results})

# NOTE: Favorites persistence would typically go here (POST/DELETE to /api/favorites)

if __name__ == '__main__':
    # Ensure the directory exists before running
    if not os.path.isdir(STATIC_DIR):
        print(f"Error: Directory {STATIC_DIR} not found. Please run setup commands first.")
    else:
        # Run on port 5001 to avoid conflicts if other services are running
        app.run(debug=True, port=5001)"}

