import json

app = Flask(__name__)

# Simple in-memory data store for MVP
restaurants = [
    {"id": 1, "name": "The Italian Place", "cuisine": "Italian", "rating": 4.5},
    {"id": 2, "name": "Spicy Wok", "cuisine": "Chinese", "rating": 4.2},
    {"id": 3, "name": "Burger Heaven", "cuisine": "American", "rating": 4.8},
]
favorites = set()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/search', methods=['GET'])
def search_restaurants():
    query = request.args.get('q', '').lower()
    results = [
        r for r in restaurants 
        if query in r['name'].lower() or query in r['cuisine'].lower()
    ]
    return jsonify(results)

@app.route('/api/favorites', methods=['GET', 'POST', 'DELETE'])
def manage_favorites():
    if request.method == 'GET':
        return jsonify(list(favorites))

    data = request.get_json()
    restaurant_id = data.get('id')

    if request.method == 'POST':
        if restaurant_id and restaurant_id not in favorites:
            favorites.add(restaurant_id)
            return jsonify({"message": "Added to favorites", "id": restaurant_id}), 200
        return jsonify({"message": "Already a favorite or invalid ID"}), 400

    if request.method == 'DELETE':
        if restaurant_id and restaurant_id in favorites:
            favorites.remove(restaurant_id)
            return jsonify({"message": "Removed from favorites", "id": restaurant_id}), 200
        return jsonify({"message": "Not in favorites or invalid ID"}), 400

if __name__ == '__main__':
    # For MVP, we'll run on a specific port
    app.run(debug=True, port=5001)"}

