    <div class="container">
        <h1>Restaurant Search & Favorites MVP</h1>

        <!-- Search Section -->
        <section>
            <h2>Search Restaurants</h2>
            <input type="text" id="search-input" placeholder="Search by name or cuisine">
            <button onclick="searchRestaurants()">Search</button>
            <ul id="search-results"></ul>
        </section>

        <hr>

        <!-- Favorites Section -->
        <section>
            <h2>My Favorites</h2>
            <ul id="favorites-list"></ul>
        </section>
    </div>

    <script>
        const searchResultsEl = document.getElementById('search-results');
        const favoritesListEl = document.getElementById('favorites-list');

        // Helper to fetch data from API
        async function fetchData(url) {
            const response = await fetch(url);
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            return response.json();
        }

        // Helper to render a restaurant item
        function renderRestaurant(restaurant, listElement, isFavorite = false) {
            const li = document.createElement('li');
            li.innerHTML = `
                <span>${restaurant.name} (${restaurant.cuisine}) - Rating: ${restaurant.rating}</span>
                <button id="btn-${restaurant.id}" onclick="${isFavorite ? `removeFavorite(${restaurant.id})` : `addFavorite(${restaurant.id}, '${restaurant.name}', '${restaurant.cuisine}', ${restaurant.rating})`}">
                    ${isFavorite ? 'Remove' : 'Add to Favorites'}
                </button>
            `;
            listElement.appendChild(li);
        }

        // Search Functionality
        async function searchRestaurants() {
            const query = document.getElementById('search-input').value;
            searchResultsEl.innerHTML = 'Loading...';
            try {
                const results = await fetchData(`/api/search?q=${encodeURIComponent(query)}`);
                searchResultsEl.innerHTML = '';
                if (results.length === 0) {
                    searchResultsEl.innerHTML = '<li>No restaurants found.</li>';
                    return;
                }
                results.forEach(r => renderRestaurant(r, searchResultsEl));
                // After search, refresh favorites list to show correct buttons
                loadFavorites(); 
            } catch (error) {
                searchResultsEl.innerHTML = `<li>Error: ${error.message}</li>`;
            }
        }

        // Favorite Management
        async function loadFavorites() {
            favoritesListEl.innerHTML = 'Loading favorites...';
            try {
                const favoriteIds = await fetchData('/api/favorites');
                favoritesListEl.innerHTML = '';

                if (favoriteIds.length === 0) {
                    favoritesListEl.innerHTML = '<li>No favorites yet.</li>';
                    return;
                }

                // Fetch all restaurants to get details for favorites
                const allRestaurants = await fetchData('/api/search?q='); // Fetch all by searching empty string

                favoriteIds.forEach(id => {
                    const favRestaurant = allRestaurants.find(r => r.id === id);
                    if (favRestaurant) {
                        renderRestaurant(favRestaurant, favoritesListEl, true);
                    }
                });

            } catch (error) {
                favoritesListEl.innerHTML = `<li>Error loading favorites: ${error.message}</li>`;
            }
        }

        async function addFavorite(id, name, cuisine, rating) {
            const response = await fetch('/api/favorites', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ id: id })
            });
            if (response.ok) {
                alert(`${name} added to favorites!`);
                loadFavorites(); // Refresh favorites list
                // Re-render search results to update button state if necessary (optional for MVP)
                searchRestaurants(); 
            } else {
                const data = await response.json();
                alert(`Failed to add: ${data.message}`);
            }
        }

        async function removeFavorite(id) {
            const response = await fetch('/api/favorites', {
                method: 'DELETE',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ id: id })
            });
            if (response.ok) {
                alert(`Restaurant removed from favorites!`);
                loadFavorites(); // Refresh favorites list
                // Re-render search results to update button state if necessary (optional for MVP)
                searchRestaurants(); 
            } else {
                const data = await response.json();
                alert(`Failed to remove: ${data.message}`);
            }
        }

        // Initial load
        document.addEventListener('DOMContentLoaded', () => {
            searchRestaurants(); // Load initial search results
            loadFavorites();     // Load initial favorites
        });
    </script>
</body>
